package com.hostel.hostelmanagement.dto; import com.hostel.hostelmanagement.enums.Role; import jakarta.validation.constraints.*; public class RegisterRequest { @NotBlank String name; @Email @NotBlank String email; @Size(min=6) String password; @NotNull Role role; String phone,department,studentId; public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public Role getRole(){return role;} public void setRole(Role v){role=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public String getStudentId(){return studentId;} public void setStudentId(String v){studentId=v;} }